import { describe, expect, it } from "vitest";
import type { Asset, Part } from "@/domain/types";
import { labelPath, labelUrl, parseScan, resolveScan } from "./scan";

/**
 * What a scan means.
 *
 * The round trips matter more than the parsing: a label is generated by one
 * function and read by another, and the only thing that proves they agree is
 * feeding the output of the first into the second.
 *
 * Several assertions here expect `unknown`. An assertion that something is not
 * found passes just as happily when nothing is findable at all, so each one is
 * paired with a control proving the record it refused to guess at really is
 * sitting in the lookups.
 */

const ASSET_TAG = "AHU-KGN-01";
const PART_NUMBER = "FLT-2101";

function asset(assetTag: string): Asset {
  return {
    organizationId: "org-1",
    id: "asset-1",
    assetTag,
    name: { en: "Air handling unit", fr: "Centrale de traitement d’air" },
    assetTypeId: "type-1",
    facilityId: "fac-1",
    locationId: "loc-1",
    manufacturer: "Norvent Systems",
    model: "NS-3689X",
    serialNumber: "H11A-47882",
    installedAt: "2019-03-15",
    status: "active",
    criticality: "high",
    parentAssetId: null,
  };
}

function part(partNumber: string): Part {
  return {
    organizationId: "org-1",
    id: "part-1",
    partNumber,
    name: { en: "Pleated air filter", fr: "Filtre à air plissé" },
    category: "filters",
    unitCost: 93.49,
    unitOfMeasure: "each",
    quantityOnHand: 9,
    reorderPoint: 4,
    facilityId: "fac-1",
    inventoryLocationId: "bin-1",
  };
}

const lookups = {
  assetByTag: (tag: string) =>
    tag === ASSET_TAG ? asset(ASSET_TAG) : undefined,
  partByNumber: (partNumber: string) =>
    partNumber === PART_NUMBER ? part(PART_NUMBER) : undefined,
};

describe("what a label holds", () => {
  it("builds an absolute address on the origin it is given", () => {
    expect(labelUrl("https://workaxis.example", "en", "asset", ASSET_TAG)).toBe(
      "https://workaxis.example/en/assets/AHU-KGN-01/label",
    );
    expect(
      labelUrl("https://workaxis.example", "fr", "part", PART_NUMBER),
    ).toBe("https://workaxis.example/fr/inventory/FLT-2101/label");
  });

  it("does not double the separator when the origin ends in one", () => {
    expect(
      labelUrl("https://workaxis.example/", "en", "asset", ASSET_TAG),
    ).toBe("https://workaxis.example/en/assets/AHU-KGN-01/label");
  });

  it("addresses the record by the identifier people say, not by its id", () => {
    // `Id` is opaque and the seed rebuilds it on every reset. A printed label
    // outlives that; the tag is what survives.
    expect(labelPath("asset", ASSET_TAG)).toContain(ASSET_TAG);
    expect(labelPath("asset", ASSET_TAG)).not.toContain("asset-1");
  });
});

describe("reading a scan back", () => {
  it("reads back the label it generated, for both kinds", () => {
    const assetLabel = labelUrl("https://x.test", "en", "asset", ASSET_TAG);
    expect(resolveScan(assetLabel, lookups)).toEqual({
      outcome: "asset",
      asset: asset(ASSET_TAG),
    });

    const partLabel = labelUrl("https://x.test", "fr", "part", PART_NUMBER);
    expect(resolveScan(partLabel, lookups)).toEqual({
      outcome: "part",
      part: part(PART_NUMBER),
    });
  });

  it("accepts the bare identifier a handheld reader types", () => {
    expect(resolveScan(ASSET_TAG, lookups).outcome).toBe("asset");
    expect(resolveScan(PART_NUMBER, lookups).outcome).toBe("part");
  });

  it("accepts lower case and surrounding whitespace", () => {
    expect(resolveScan("  ahu-kgn-01 \n", lookups).outcome).toBe("asset");
  });

  it("reads the path and ignores the host", () => {
    // A scan never navigates to the address it was handed; it looks the
    // identifier up in our own records. So a code printed by someone else
    // cannot send a technician anywhere.
    const foreign = `https://somewhere-else.test/en/assets/${ASSET_TAG}/label`;
    expect(resolveScan(foreign, lookups).outcome).toBe("asset");

    const parsed = parseScan(foreign);
    expect(parsed).toEqual({
      source: "url",
      kind: "asset",
      identifier: ASSET_TAG,
    });
  });

  it("reads a record address that has no /label on the end", () => {
    expect(resolveScan(`/en/assets/${ASSET_TAG}`, lookups).outcome).toBe(
      "asset",
    );
  });
});

describe("refusing to guess", () => {
  it("answers unknown when the label names assets but carries a stock number", () => {
    const mislabelled = `https://x.test/en/assets/${PART_NUMBER}/label`;
    expect(resolveScan(mislabelled, lookups)).toEqual({
      outcome: "unknown",
      scanned: mislabelled,
    });
  });

  it("would notice — that stock number is findable, the refusal is real", () => {
    // The control. Without it the assertion above would pass just as well on
    // empty lookups, and would be measuring nothing.
    expect(lookups.partByNumber(PART_NUMBER)).toBeDefined();
  });

  it("answers unknown for an identifier nobody holds", () => {
    expect(resolveScan("AHU-KGN-99", lookups).outcome).toBe("unknown");
  });

  it("would notice — a neighbouring identifier does resolve", () => {
    // The control for the assertion above: the lookups are populated, so
    // `unknown` is a refusal rather than an empty table.
    expect(resolveScan(ASSET_TAG, lookups).outcome).toBe("asset");
  });

  it("answers unknown for empty and meaningless text", () => {
    for (const text of ["", "   ", "hello", "https://x.test/en/dashboard"]) {
      expect(resolveScan(text, lookups).outcome).toBe("unknown");
    }
  });

  it("answers unknown for malformed percent-encoding", () => {
    expect(
      resolveScan("https://x.test/en/assets/%E0%A4%A/label", lookups),
    ).toHaveProperty("outcome", "unknown");
  });

  it("would notice a round trip that had stopped working", () => {
    // The control for the round trips: strip the module segment out of a real
    // label and the parse must fail. If this returned a target, the round-trip
    // assertions above would be passing on any string at all.
    const label = labelUrl("https://x.test", "en", "asset", ASSET_TAG);
    expect(parseScan(label)).not.toBeNull();
    expect(parseScan(label.replace("/assets/", "/nowhere/"))).toBeNull();
  });
});
